// hub-presence → Redis (post-failover)
{
  "error": "ReplyError",
  "command": "HGET presence:sock_9920...",
  "detail": "READONLY You can't write against a read only replica.",
  "action_taken": "DROP_BROADCAST"
}

// hub-push delivery log
{
  "socket_id": "sock_9920...",
  "delivered": false,
  "reason": "no_target_from_presence",
  "fallback": "none"   // <-- the bug: should have queued a poll
}

// Kafka record on orders.created
// key: ord_A991...
{
  "orderId": "ord_A991...",
  "items": [{ "skuId": "sku_magboot_gravlock_9", "qty": 1 }],
  "shippingRegion": "luna-colony"
}

// Kafka record on orders.created
// key: ord_B004...
{
  "orderId": "ord_B004...",
  "items": [{ "skuId": "sku_magboot_gravlock_9", "qty": 1 }],
  "shippingRegion": "luna-colony"
}

// DynamoDB UpdateItem (order A)  → SUCCESS  available 1 → 0
// DynamoDB UpdateItem (order B)  → ConditionalCheckFailedException
{
  "error": "ConditionalCheckFailedException",
  "table": "inventory-stock",
  "key": { "skuId": "sku_magboot_gravlock_9", "warehouse": "wh-luna-1" },
  "attemptedBy": "ord_B004..."
}

// Kafka record on inventory.reserved
// key: ord_A991...
{
  "reservationId": "rsv_77C2...",
  "orderId": "ord_A991...",
  "lines": [{ "skuId": "sku_magboot_gravlock_9", "qty": 1, "warehouse": "wh-luna-1" }]
}

// hub.broadcasts — the message we wish we hadn't sent to Order B
{
  "socket_id": "[redacted]",
  "event_name": "order-confirmed",
  "payload": { "orderId": "ord_B004...", "message": "Order confirmed!" }
}

// Kafka record on payments.failed
// key: orderId
{
  "orderId": "ord_5F1A...",
  "reason": "capture_timeout",
  "retryable": true,
  "attempt": 1,
  "failedAt": "2026-03-12T14:03:52.118Z"
}

